draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 50, H/2);
  ctx.lineTo(W/2 + Math.sin(t) * 50 + Math.cos(t) * 30, H/2 + Math.sin(t) * 10);
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t) * 70, H/2 + 100, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.cos(t) * 70, H/2 + 100);
  ctx.lineTo(W/2 + Math.cos(t) * 70 + Math.sin(t) * 40, H/2 + 100 + Math.cos(t) * 20);
  ctx.stroke();

  // rabbit
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t) * 20, H/2 + 50, 25, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t) * 20, H/2 + 50);
  ctx.lineTo(W/2 + Math.sin(t) * 20 + Math.cos(t) * 20, H/2 + 50 + Math.sin(t) * 10);
  ctx.stroke();

  ctx.restore();
}
